const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const action = text(input.action || 'list').toLowerCase();
const clinic_name = text(input.clinic_name);
const gateway_client_id =
  Number(input.gateway_client_id ?? 0);
const client_name = text(input.client_name);
const channel = text(input.channel).toLowerCase();
const provider_name = text(input.provider_name);
const auth_mode =
  text(input.auth_mode || 'api_key').toLowerCase();
const api_key = text(input.api_key);
const signature_verifier_url =
  text(input.signature_verifier_url);
const signature_credential_reference =
  text(input.signature_credential_reference);

let allowed_ip_addresses =
  input.allowed_ip_addresses ?? [];

let metadata = input.metadata ?? {};

try {
  if (typeof allowed_ip_addresses === 'string') {
    allowed_ip_addresses =
      JSON.parse(allowed_ip_addresses || '[]');
  }
} catch {
  allowed_ip_addresses = null;
}

try {
  if (typeof metadata === 'string') {
    metadata = JSON.parse(metadata || '{}');
  }
} catch {
  metadata = null;
}

const rate_limit_requests =
  Number(input.rate_limit_requests ?? 120);
const rate_limit_window_seconds =
  Number(input.rate_limit_window_seconds ?? 60);
const replay_window_seconds =
  Number(input.replay_window_seconds ?? 86400);
const actor_name = text(input.actor_name);
const limit = Number(input.limit ?? 100);
const confirm_action = bool(input.confirm_action);

const actions = [
  'create',
  'update',
  'rotate_api_key',
  'activate',
  'deactivate',
  'get',
  'list',
];

const channels = [
  'whatsapp',
  'sms',
  'phone',
  'telegram',
  'webchat',
  'manual',
  'api',
  'email',
  'web_push',
  'in_app',
];

const authModes = [
  'api_key',
  'provider_signature',
  'development_none',
];

const errors = [];

if (!actions.includes(action)) {
  errors.push({
    field: 'action',
    message: 'اقدام معتبر نیست.',
  });
}

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (
  !Number.isInteger(gateway_client_id) ||
  gateway_client_id < 0
) {
  errors.push({
    field: 'gateway_client_id',
    message: 'شناسه Gateway Client معتبر نیست.',
  });
}

if (
  ['create', 'update', 'rotate_api_key', 'activate', 'deactivate', 'get']
    .includes(action) &&
  gateway_client_id < 1 &&
  !client_name
) {
  errors.push({
    field: 'client_reference',
    message: 'شناسه یا نام Client الزامی است.',
  });
}

if (
  action === 'create' &&
  !channels.includes(channel)
) {
  errors.push({
    field: 'channel',
    message: 'کانال معتبر نیست.',
  });
}

if (!authModes.includes(auth_mode)) {
  errors.push({
    field: 'auth_mode',
    message: 'حالت Authentication معتبر نیست.',
  });
}

if (
  action === 'create' &&
  auth_mode === 'api_key' &&
  api_key.length < 16
) {
  errors.push({
    field: 'api_key',
    message: 'API Key باید حداقل 16 کاراکتر باشد.',
  });
}

if (
  action === 'rotate_api_key' &&
  api_key.length < 16
) {
  errors.push({
    field: 'api_key',
    message: 'API Key جدید باید حداقل 16 کاراکتر باشد.',
  });
}

if (
  auth_mode === 'provider_signature' &&
  action === 'create' &&
  !signature_credential_reference
) {
  errors.push({
    field: 'signature_credential_reference',
    message: 'مرجع Credential امضای Provider الزامی است.',
  });
}

if (
  signature_verifier_url &&
  !/^https?:\/\/.+/i.test(signature_verifier_url)
) {
  errors.push({
    field: 'signature_verifier_url',
    message: 'آدرس Signature Verifier معتبر نیست.',
  });
}

if (
  !Array.isArray(allowed_ip_addresses) ||
  allowed_ip_addresses.some(
    (value) =>
      typeof value !== 'string' ||
      value.trim().length === 0
  )
) {
  errors.push({
    field: 'allowed_ip_addresses',
    message: 'لیست IPهای مجاز معتبر نیست.',
  });

  allowed_ip_addresses = [];
}

if (
  !metadata ||
  Array.isArray(metadata) ||
  typeof metadata !== 'object'
) {
  errors.push({
    field: 'metadata',
    message: 'metadata باید یک شیء JSON باشد.',
  });

  metadata = {};
}

if (
  !Number.isInteger(rate_limit_requests) ||
  rate_limit_requests < 1 ||
  rate_limit_requests > 100000
) {
  errors.push({
    field: 'rate_limit_requests',
    message: 'حد درخواست معتبر نیست.',
  });
}

if (
  !Number.isInteger(rate_limit_window_seconds) ||
  rate_limit_window_seconds < 1 ||
  rate_limit_window_seconds > 86400
) {
  errors.push({
    field: 'rate_limit_window_seconds',
    message: 'بازه Rate Limit معتبر نیست.',
  });
}

if (
  !Number.isInteger(replay_window_seconds) ||
  replay_window_seconds < 60 ||
  replay_window_seconds > 604800
) {
  errors.push({
    field: 'replay_window_seconds',
    message: 'Replay Window معتبر نیست.',
  });
}

if (
  !Number.isInteger(limit) ||
  limit < 1 ||
  limit > 500
) {
  errors.push({
    field: 'limit',
    message: 'Limit معتبر نیست.',
  });
}

if (
  !['get', 'list'].includes(action) &&
  !actor_name
) {
  errors.push({
    field: 'actor_name',
    message: 'نام انجام‌دهنده الزامی است.',
  });
}

if (
  !['get', 'list'].includes(action) &&
  confirm_action !== true
) {
  errors.push({
    field: 'confirm_action',
    message: 'اقدام باید تأیید شود.',
  });
}

return [{
  json: {
    action,
    clinic_name,
    gateway_client_id,
    client_name,
    channel,
    provider_name,
    auth_mode,
    api_key,
    signature_verifier_url,
    signature_credential_reference,
    allowed_ip_addresses,
    allowed_ip_addresses_text:
      JSON.stringify(allowed_ip_addresses),
    rate_limit_requests,
    rate_limit_window_seconds,
    replay_window_seconds,
    metadata,
    metadata_text:
      JSON.stringify(metadata),
    actor_name,
    limit,
    confirm_action,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
